            val writeReturn = { value: List<OcrWord> -> uniffiOutReturn.setValue(FfiConverterSequenceTypeOcrWord.lower(value)) }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }
    internal object `maxDimension`: UniffiCallbackInterfaceTextRecognizerMethod1 {
        override fun callback(`uniffiHandle`: Long,`uniffiOutReturn`: IntByReference,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeTextRecognizer.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`maxDimension`(
                )
            }
            val writeReturn = { value: kotlin.UInt -> uniffiOutReturn.setValue(FfiConverterUInt.lower(value)) }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }

    internal object uniffiFree: UniffiCallbackInterfaceFree {
        override fun callback(handle: Long) {
            FfiConverterTypeTextRecognizer.handleMap.remove(handle)
        }
    }

    internal object uniffiClone: UniffiCallbackInterfaceClone {
        override fun callback(handle: Long): Long {
            return FfiConverterTypeTextRecognizer.handleMap.clone(handle)
        }
    }

    internal var vtable = UniffiVTableCallbackInterfaceTextRecognizer.UniffiByValue(
        uniffiFree,
        uniffiClone,
        `recognize`,
        `maxDimension`,
    )

    // Registers the foreign callback with the Rust side.
    // This method is generated for each callback interface.
