/**
 * @suppress
 */
public object FfiConverterTypeTextRecognizer: FfiConverter<TextRecognizer, Long> {
    internal val handleMap = UniffiHandleMap<TextRecognizer>()

    override fun lower(value: TextRecognizer): Long {
        if (value is TextRecognizerImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): TextRecognizer {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return TextRecognizerImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): TextRecognizer {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: TextRecognizer) = 8UL

    override fun write(value: TextRecognizer, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



