sealed class CoreException: kotlin.Exception() {
    
    /**
     * something went wrong (the message says what)
     */
    class Failed(
        
        val `reason`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreException = FfiConverterTypeCoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeCoreError : FfiConverterRustBuffer<CoreException> {
    override fun read(buf: ByteBuffer): CoreException {
        

        return when(buf.getInt()) {
            1 -> CoreException.Failed(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CoreException): ULong {
        return when(value) {
            is CoreException.Failed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: CoreException, buf: ByteBuffer) {
        when(value) {
            is CoreException.Failed -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





/**
 * Why a TV couldn't be connected.
 */
sealed class PairException: kotlin.Exception() {
    
    /**
     * not the code the TV shows
     */
    class WrongCode(
        ) : PairException() {
        override val message
            get() = ""
    }
    
    /**
     * too many wrong codes: the TV shows a new one
     */
    class TooMany(
        ) : PairException() {
        override val message
            get() = ""
    }
    
    /**
     * no answer, or not the TV app
     */
    class NoAnswer(
        ) : PairException() {
        override val message
            get() = ""
    }
    
    /**
     * the TV page server isn't running (`start_tv_server`), or there's no home network
     */
    class NotSharing(
        ) : PairException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<PairException> {
        override fun lift(error_buf: RustBuffer.ByValue): PairException = FfiConverterTypePairError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypePairError : FfiConverterRustBuffer<PairException> {
    override fun read(buf: ByteBuffer): PairException {
        

        return when(buf.getInt()) {
            1 -> PairException.WrongCode()
            2 -> PairException.TooMany()
            3 -> PairException.NoAnswer()
            4 -> PairException.NotSharing()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: PairException): ULong {
        return when(value) {
            is PairException.WrongCode -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is PairException.TooMany -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is PairException.NoAnswer -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is PairException.NotSharing -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: PairException, buf: ByteBuffer) {
        when(value) {
            is PairException.WrongCode -> {
                buf.putInt(1)
                Unit
            }
            is PairException.TooMany -> {
                buf.putInt(2)
                Unit
            }
            is PairException.NoAnswer -> {
                buf.putInt(3)
                Unit
            }
            is PairException.NotSharing -> {
                buf.putInt(4)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




